import { Injectable } from '@angular/core';
import { Register } from '../models/Register';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { Login } from '../models/Login';
import { LoginResponse } from '../models/LoginResponse';

@Injectable({
  providedIn: 'root',
})
export class UserService {
  constructor(private httpClient: HttpClient) {}

  // memo: HttpClient is configure by a proxy in proxy.conf.json
  register(user: Register): Observable<Object> {
    return this.httpClient.post('/api/register', user);
  }

  login(credentials: Login): Observable<LoginResponse> {
    return this.httpClient.post<LoginResponse>('/api/login', credentials);
  }
}

import { Component, DestroyRef, inject, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { MaterialModule } from '../../shared/material.module';
import { UserService } from '../../core/service/user.service';
import { Register } from '../../core/models/Register';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({
  selector: 'app-register',
  imports: [CommonModule, MaterialModule],
  templateUrl: './register.component.html',
  standalone: true,
  styleUrl: './register.component.css'
})
export class RegisterComponent implements OnInit {
  private userService = inject(UserService);
  private formBuilder = inject(FormBuilder);
  private destroyRef = inject(DestroyRef);
  registerForm: FormGroup = new FormGroup({});
  submitted: boolean = false;

  ngOnInit() {
    this.registerForm = this.formBuilder.group(
      {
        firstName: ['', Validators.required],
        lastName: ['', Validators.required],
        login: ['', Validators.required],
        password: ['', Validators.required]
      },
    );
  }

  get form() {
    return this.registerForm.controls;
  }

  onSubmit(): void {
    this.submitted = true;
    if (this.registerForm.invalid) {
      return;
    }
    const registerUser: Register = {
      firstName: this.registerForm.get('firstName')?.value,
      lastName: this.registerForm.get('lastName')?.value,
      login: this.registerForm.get('login')?.value,
      password: this.registerForm.get('password')?.value
    };
    this.userService.register(registerUser)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(
      () => {
        alert('SUCCESS!! :-)');
        // TODO : router l'utilisateur vers la page de login
      },
    );
  }

  onReset(): void {
    this.submitted = false;
    this.registerForm.reset();
  }
}
<div class="card m-3">
  <h5 class="card-header">Registration Form</h5>
  <div class="card-body">
    <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">
      <div class="form-row">
        <div class="form-group col-5">
          <label>First Name</label>
          <input
            type="text"
            formControlName="firstName"
            data-cy="register-firstName"
            class="form-control"
            [ngClass]="{ 'is-invalid': submitted && form['firstName'].errors }"
          />
          @if (submitted && form["firstName"].errors) {
            <div class="invalid-feedback" data-cy="register-firstName-required">
              @if (form["firstName"].errors?.["required"]) {
                <div>First Name is required</div>
              }
            </div>
          }
        </div>
        <div class="form-group col-5">
          <label>Last Name</label>
          <input
            type="text"
            formControlName="lastName"
            data-cy="register-lastName"
            class="form-control"
            [ngClass]="{ 'is-invalid': submitted && form['lastName'].errors }"
          />
          @if (submitted && form["lastName"].errors) {
            <div class="invalid-feedback" data-cy="register-lastName-required">
              @if (form["lastName"].errors?.["required"]) {
                <div>Last Name is required</div>
              }
            </div>
          }
        </div>
      </div>
      <div class="form-group">
        <label>Login</label>
        <input
          type="text"
          formControlName="login"
          data-cy="register-login"
          class="form-control"
          [ngClass]="{ 'is-invalid': submitted && form['login'].errors }"
        />
        @if (submitted && form["login"].errors) {
          <div class="invalid-feedback" data-cy="register-login-required">
            @if (form["login"].errors?.["required"]) {
              <div>Login is required</div>
            }
          </div>
        }
      </div>

      <div class="form-group">
        <label>Password</label>
        <input
          type="text"
          formControlName="password"
          data-cy="register-password"
          class="form-control"
          [ngClass]="{ 'is-invalid': submitted && form['password'].errors }"
        />
        @if (submitted && form["password"].errors) {
          <div class="invalid-feedback" data-cy="register-password-required">
            @if (form["password"].errors?.["required"]) {
              <div>password is required</div>
            }
          </div>
        }
      </div>
      <div class="text-center">
        <button class="btn btn-primary mr-1" data-cy="register-submit">
          Register
        </button>
        <button
          class="btn btn-secondary"
          type="reset"
          (click)="onReset()"
          data-cy="register-cancel"
        >
          Cancel
        </button>
      </div>
    </form>
  </div>
</div>

import { Injectable } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly TOKEN_KEY = 'auth_token';

  setToken(token: string) {
    localStorage.setItem(this.TOKEN_KEY, token);
  }

  getToken(): string | null {
    return localStorage.getItem(this.TOKEN_KEY);
  }

  clearToken() {
    localStorage.removeItem(this.TOKEN_KEY);
  }

  isAuthenticated(): boolean {
    if (!this.getToken()) {
      return false;
    }

    try {
      const payload = JSON.parse(atob(this.getToken()!.split('.')[1]));
      const exp = payload.exp * 1000;
      return exp > Date.now();
    } catch (e) {
      return false;
    }
  }
}

import { CommonModule } from '@angular/common';
import { Component, DestroyRef, inject, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { MaterialModule } from '../../shared/material.module';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { UserService } from '../../core/service/user.service';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Login } from '../../core/models/Login';
import { AuthService } from '../../core/service/auth.service';
import { finalize } from 'rxjs';

@Component({
  selector: 'app-login',
  imports: [CommonModule, MaterialModule],
  templateUrl: './login.component.html',
  standalone: true,
  styleUrl: './login.component.css',
})
export class LoginComponent implements OnInit {
  private userService = inject(UserService);
  private AuthService = inject(AuthService);
  private formBuilder = inject(FormBuilder);
  private destroyRef = inject(DestroyRef);
  private router = inject(Router);
  public errorMessage: string | null = null;
  public loading: boolean = false;

  loginForm: FormGroup = new FormGroup({});
  submitted: boolean = false;

  ngOnInit(): void {
    this.loginForm = this.formBuilder.group({
      login: ['', Validators.required],
      password: ['', Validators.required],
    });
  }

  onSubmit(): void {
    this.submitted = true;

    if (this.loginForm.invalid) {
      return;
    }

    this.loading = true;

    const credentials: Login = {
      login: this.loginForm.get('login')?.value,
      password: this.loginForm.get('password')?.value,
    };

    this.userService
      .login(credentials)
      .pipe(
        takeUntilDestroyed(this.destroyRef),
        finalize(() => {
          this.loading = false;
        }),
      )
      .subscribe({
        // NoError function
        next: (res) => {
          this.AuthService.setToken(res.token);
          this.router.navigate(['/dashboard']);
        },
        // Handle Error
        error: (err) => {
          this.errorMessage = err.error.message;
        },
      });
  }

  onReset(): void {
    this.submitted = false;
    this.loginForm.reset();
    this.errorMessage = null;
  }
}
<div class="card m-3">
  <h5 class="card-header">Login</h5>

  <div class="card-body">
    <form [formGroup]="loginForm" (ngSubmit)="onSubmit()">
      <div class="form-group">
        <label for="login">Login</label>
        <input
          type="text"
          id="login"
          class="form-control"
          placeholder="Enter your login"
          formControlName="login"
          data-cy="login-input"
        />
      </div>
      <div
        class="text-danger"
        *ngIf="submitted && loginForm.get('login')?.hasError('required')"
        data-cy="login-required"
      >
        Login requis
      </div>

      <div class="form-group">
        <label for="password">Password</label>
        <input
          type="password"
          id="password"
          class="form-control"
          placeholder="Enter your password"
          formControlName="password"
          data-cy="password-input"
        />
      </div>
      <div
        class="text-danger"
        *ngIf="submitted && loginForm.get('password')?.hasError('required')"
        data-cy="password-required"
      >
        Mot de passe requis
      </div>

      <div class="text-danger" *ngIf="errorMessage" data-cy="login-error">
        {{ errorMessage }}
      </div>
      <div class="text-center">
        <button
          type="submit"
          class="btn btn-primary mr-1"
          [disabled]="loading"
          data-cy="login-submit"
        >
          {{ loading ? "Loading..." : "Login" }}
        </button>

        <button
          type="button"
          class="btn btn-secondary"
          (click)="onReset()"
          [disabled]="loading"
          data-cy="login-cancel"
        >
          Cancel
        </button>
      </div>
    </form>
  </div>
</div>

