import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../core/service/auth.service';

export const AuthGuard = () => {
  const auth = inject(AuthService);
  const router = inject(Router);

  if (!auth.isAuthenticated()) {
    alert('Vous avez été déconnecté. Veuillez vous reconnecter.');
    router.navigateByUrl('/login');
    return false;
  }
  return true;
};

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { AuthService } from './auth.service';
import { Student } from '../models/Student';
import { StudentRegister } from '../models/StudentRegister';

@Injectable({
  providedIn: 'root',
})
export class StudentService {
  constructor(
    private httpClient: HttpClient,
    private authService: AuthService,
  ) {}

  getAllStudents(): Observable<Student[]> {
    return this.httpClient.get<Student[]>('/api/student', {
      headers: { Authorization: 'Bearer ' + this.authService.getToken() },
    });
  }

  getStudentById(studentId: number): Observable<Student> {
    return this.httpClient.get<Student>(`/api/student/${studentId}`, {
      headers: { Authorization: 'Bearer ' + this.authService.getToken() },
    });
  }

  createStudent(student: StudentRegister): Observable<Object> {
    return this.httpClient.post<Object>('/api/student', student, {
      headers: { Authorization: 'Bearer ' + this.authService.getToken() },
    });
  }

  deleteStudent(studentId: number): Observable<Object> {
    return this.httpClient.delete(`/api/student/${studentId}`, {
      headers: { Authorization: 'Bearer ' + this.authService.getToken() },
    });
  }

  updateStudent(
    studentId: number,
    student: StudentRegister,
  ): Observable<Student> {
    return this.httpClient.put<Student>(`/api/student/${studentId}`, student, {
      headers: { Authorization: 'Bearer ' + this.authService.getToken() },
    });
  }
}

import { Component, DestroyRef, inject } from '@angular/core';
import { MaterialModule } from '../../../../shared/material.module';
import { CommonModule } from '@angular/common';
import { StudentService } from '../../../../core/service/student.service';
import { catchError, of, shareReplay } from 'rxjs';
import { Router } from '@angular/router';

@Component({
  selector: 'app-studentlist',
  imports: [CommonModule, MaterialModule],
  templateUrl: './studentlist.component.html',
  standalone: true,
})
export class StudentlistComponent {
  private studentService = inject(StudentService);
  private router = inject(Router);
  public errorMessage: string | null = null;

  students$ = this.studentService.getAllStudents().pipe(
    catchError((err) => {
      if (err.status === 401) {
        alert('Vous avez été déconnecté. Veuillez vous reconnecter.');
        this.router.navigate(['/login']);
        return of([]);
      }
      this.errorMessage = 'Erreur chargement';
      return of([]);
    }),
    shareReplay(1),
  );

  viewStudent(studentId: number): void {
    this.router.navigate(['/dashboard/student', studentId, 'detail']);
  }

  viewDeleteStudent(studentId: number): void {
    this.router.navigate(['/dashboard/student', studentId, 'delete']);
  }
}
<div class="card">
  <h5 class="card-header">Liste des étudiants</h5>

  <div class="card-body">
    <div class="row mb-3">
      <div class="col-md-6">
        <input
          type="text"
          class="form-control"
          placeholder="Rechercher par nom, prénom ou email"
        />
      </div>
    </div>

    <div
      class="alert alert-danger mt-3"
      *ngIf="errorMessage"
      data-cy="student-list-error"
    >
      {{ errorMessage }}
    </div>

    <div class="table-responsive">
      <table class="table table-striped table-hover">
        <thead class="thead-light">
          <tr>
            <th>#</th>
            <th>Prénom</th>
            <th>Nom</th>
            <th>Email</th>
            <th class="text-center">Actions</th>
          </tr>
        </thead>

        <tbody>
          <tr
            *ngFor="let student of students$ | async; index as i"
            data-cy="student-row"
          >
            <td>{{ i + 1 }}</td>
            <td>{{ student.firstName }}</td>
            <td>{{ student.lastName }}</td>
            <td>{{ student.email }}</td>
            <td class="text-center">
              <button
                class="btn btn-sm btn-info mr-1"
                (click)="viewStudent(student.id)"
                data-cy="student-view"
              >
                Voir le détail
              </button>
              <button
                class="btn btn-sm btn-danger mr-1"
                (click)="viewDeleteStudent(student.id)"
                data-cy="student-delete"
              >
                Supprimer
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <div
      *ngIf="(students$ | async)?.length === 0"
      class="alert alert-info mt-3"
    >
      Aucun étudiant trouvé.
    </div>
  </div>
</div>

import { CommonModule } from '@angular/common';
import { Component, DestroyRef, inject, OnInit } from '@angular/core';
import { MaterialModule } from '../../../../shared/material.module';
import { StudentService } from '../../../../core/service/student.service';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { StudentRegister } from '../../../../core/models/StudentRegister';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Router } from '@angular/router';

@Component({
  selector: 'app-studentcreate',
  templateUrl: './studentcreate.component.html',
  imports: [CommonModule, MaterialModule],
})
export class StudentCreateComponent implements OnInit {
  private studentService = inject(StudentService);
  private formBuilder = inject(FormBuilder);
  private destroyRef = inject(DestroyRef);
  private router = inject(Router);

  errorMessage: string | null = null;
  studentForm: FormGroup = new FormGroup({});

  ngOnInit(): void {
    this.studentForm = this.formBuilder.group({
      firstName: ['', Validators.required],
      lastName: ['', Validators.required],
      email: ['', [Validators.required, Validators.email]],
    });
  }

  onSubmit(): void {
    if (this.studentForm.invalid) {
      this.studentForm.markAllAsTouched();
      return;
    }

    const newStudent: StudentRegister = {
      firstName: this.studentForm.get('firstName')?.value,
      lastName: this.studentForm.get('lastName')?.value,
      email: this.studentForm.get('email')?.value,
    };

    this.studentService
      .createStudent(newStudent)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (student) => {
          this.studentForm.reset();
          alert('Student created successfully!');
          this.router.navigate(['/dashboard/student-list']);
        },
        error: (error) => {
          if (error.status === 401) {
            alert('Vous avez été déconnecté. Veuillez vous reconnecter.');
            this.router.navigate(['/login']);
            return;
          }

          this.errorMessage = "Erreur durant la création de l'étudiant.";
        },
      });
  }

  onReset(): void {
    this.studentForm.reset();
    this.errorMessage = null;
  }
}
