        />
        <div
          *ngIf="
            studentForm.get('email')?.touched &&
            studentForm.get('email')?.invalid
          "
        >
          <small
            class="text-danger"
            *ngIf="studentForm.get('email')?.errors?.['required']"
          >
            L'email est obligatoire
          </small>

          <small
            class="text-danger"
            *ngIf="studentForm.get('email')?.errors?.['email']"
          >
            Format d’email invalide
          </small>
