        >
          Annuler
        </button>

        <button
          type="submit"
          class="btn btn-primary"
          data-cy="student-create-submit"
        >
          Créer
        </button>
      </div>
    </form>
    <div class="text-danger mt-3" *ngIf="errorMessage">{{ errorMessage }}</div>
  </div>
