        />

        <div
          *ngIf="
            updateForm.get('email')?.touched && updateForm.get('email')?.invalid
          "
          data-cy="student-update-error"
        >
          <small
            class="text-danger"
            *ngIf="updateForm.get('email')?.errors?.['required']"
          >
            L’email est obligatoire
          </small>

          <small
            class="text-danger"
            *ngIf="updateForm.get('email')?.errors?.['email']"
          >
