      </div>

      <div
        class="text-danger mt-3"
        *ngIf="errorMessage"
        data-cy="student-update-api-error"
      >
        {{ errorMessage }}
      </div>

      <div class="d-flex justify-content-end">
        <button
          type="button"
          class="btn btn-secondary mr-2"
          (click)="onReset()"
          data-cy="student-update-cancel"
        >
          Annuler
